public static WeightedRandomList<MobSpawnSettings.SpawnerData> mobsAt(ServerLevel p_220444_, StructureManager p_220445_, ChunkGenerator p_220446_, MobCategory p_220447_, BlockPos p_220448_, @Nullable Holder<Biome> p_220449_) {
    return net.minecraftforge.event.ForgeEventFactory.getPotentialSpawns(p_220444_, p_220447_, p_220448_, NaturalSpawner.isInNetherFortressBounds(p_220448_, p_220444_, p_220447_, p_220445_) ? p_220445_.registryAccess().registryOrThrow(Registries.STRUCTURE).getOrThrow(BuiltinStructures.FORTRESS).spawnOverrides().get(MobCategory.MONSTER).spawns() : p_220446_.getMobsAt(p_220449_ != null ? p_220449_ : p_220444_.getBiome(p_220448_), p_220445_, p_220447_, p_220448_));
}

public static List<EntityType<?>> getEntityTypesConfig(List<? extends String> config){
    List<EntityType<?>> list = new ArrayList<>();
    if (!config.isEmpty()){
        for (String id : config){
            EntityType<?> entityType = ForgeRegistries.ENTITY_TYPES.getValue(new ResourceLocation(id));
            if (entityType != null){
                list.add(entityType);
            }
        }
    }
    return list;
}

public static boolean hasEntityTypesConfig(List<? extends String> config, EntityType<?> entityType){
    return !getEntityTypesConfig(config).isEmpty() && getEntityTypesConfig(config).contains(entityType);
}

public class ModBlocks {
    public static DeferredRegister<Block> BLOCKS = DeferredRegister.create(ForgeRegistries.BLOCKS, Goety.MOD_ID);
    public static final Map<ResourceLocation, BlockLootSetting> BLOCK_LOOT = new HashMap<>();

    @SuppressWarnings("removal")
    public static void init(){
        ModBlocks.BLOCKS.register(FMLJavaModLoadingContext.get().getModEventBus());
    }

public static final RegistryObject<ModChestBlock> RAIDING_CHEST = isterRegister("raiding_chest", () -> new ModChestBlock(Block.Properties.of().instrument(NoteBlockInstrument.BASS).strength(2.5F).sound(SoundType.WOOD)));
public static final RegistryObject<ModTrappedChestBlock> TRAPPED_RAIDING_CHEST = isterRegister("trapped_raiding_chest", () -> new ModTrappedChestBlock(Block.Properties.of().instrument(NoteBlockInstrument.BASS).strength(2.5F).sound(SoundType.WOOD)));
public static final RegistryObject<Block> FORBIDDEN_GRASS = register("forbidden_grass", ForbiddenGrassBlock::new, true, LootTableType.EMPTY);
public static final RegistryObject<Block> HOOK_BELL = register("hook_bell", HookBellBlock::new);
public static final RegistryObject<Block> SHRIEKING_OBELISK = register("shriek_obelisk", ShriekObeliskBlock::new);
public static final RegistryObject<Block> NECRO_BRAZIER = register("necro_brazier", NecroBrazierBlock::new);

public static final RegistryObject<Block> COBBLED_DIRT = register("cobbled_dirt", () ->
        new Block(BlockBehaviour.Properties.of().mapColor(MapColor.DIRT).sound(SoundType.BASALT).requiresCorrectToolForDrops().strength(1.5F)), true, LootTableType.EMPTY);
public static final RegistryObject<Block> SNOWY_DIRT = register("snowy_dirt", () ->
        new Block(BlockBehaviour.Properties.copy(Blocks.DIRT)), true, LootTableType.EMPTY);
public static final RegistryObject<Block> DARK_DIRT = register("dark_dirt", () ->
        new Block(BlockBehaviour.Properties.copy(Blocks.DIRT).mapColor(MapColor.TERRACOTTA_BLACK)));
public static final RegistryObject<Block> COBBLED_DARK_DIRT = register("cobbled_dark_dirt", () ->
        new Block(BlockBehaviour.Properties.of().mapColor(MapColor.TERRACOTTA_BLACK).sound(SoundType.BASALT).requiresCorrectToolForDrops().strength(1.5F)), true, LootTableType.EMPTY);
public static final RegistryObject<Block> SNOWY_DARK_DIRT = register("snowy_dark_dirt", () ->
        new Block(BlockBehaviour.Properties.copy(DARK_DIRT.get())), true, LootTableType.EMPTY);
public static final RegistryObject<Block> GRAVE_SOIL = register("grave_soil", () ->
        new GraveSoilBlock(BlockBehaviour.Properties.copy(DARK_DIRT.get()).sound(SoundType.SOUL_SOIL)));

public static <T extends Block> RegistryObject<T> register(final String string, final Supplier<? extends T> sup){
    return register(string, sup, true);
}

public static <T extends Block> RegistryObject<T> register(final String string, final Supplier<? extends T> sup, boolean blockItemDefault){
    return register(string, sup, blockItemDefault, LootTableType.DROP);
}

public static <T extends Block> RegistryObject<T> register(final String string, final Supplier<? extends T> sup, boolean blockItemDefault, LootTableType lootTableType) {
    RegistryObject<T> block = BLOCKS.register(string, sup);
    BLOCK_LOOT.put(block.getId(), new BlockLootSetting(blockItemDefault, lootTableType));
    if (blockItemDefault) {
        ModItems.ITEMS.register(string,
                () -> new BlockItemBase(block.get()));
    }
    return block;
}

package com.Polarice3.Goety.common.ritual.type;

import com.Polarice3.Goety.api.ritual.IRitualType;
